 undo(){if(this.hist.length){this.restore(this.hist,this.fut);sfx('move');}else this.say('Nothing to undo.');},redo(){if(this.fut.length){this.restore(this.fut,this.hist);sfx('move');}else this.say('Nothing to redo.');},
 say(s,c){this.toast=s;this.toastT=3.2;this.toastC=c||'#ffe07a';},
 snapping(){return this.snapOn!==!!(held.AltLeft||held.AltRight);},
