 tlPiece(wx,wy){const b=buildPiece(this.piece,this.prot,this.pflip);return[this.sn(wx-(b.w>>1)),this.sn(wy-(b.h>>1)),b];},
 putPiece(x,y){const m=this.map,b=buildPiece(this.piece,this.prot,this.pflip);if(x+b.w<=0||y+b.h<=0||x>=m.w||y>=m.h){this.say('That is outside the map.','#ffb040');sfx('nope');return;}let fl=this.pflip?1:0;if(m.mode==='mirror'&&x+b.w/2>=m.w/2){x=m.w-x-b.w;fl^=1;}this.snap();const op=['P',this.piece,x,y,this.prot,fl];m.ops.push(op);this.S.op(op);this.afterOp(x-2,x+b.w+2);sfx('assign');},
 copyOp(sx,sy,w,h,dx,dy,fl=0){const m=this.map;if(m.mode==='mirror'){const half=m.w>>1;if(sx+w/2>=half){sx=m.w-sx-w;fl^=1;}if(dx+w/2>=half){dx=m.w-dx-w;fl^=1;}}this.snap();const op=['C',sx,sy,w,h,dx,dy,fl];m.ops.push(op);this.S.op(op);this.afterOp(dx-2,dx+w+2);sfx('assign');},
 dupReg(ax,ay){const r=this.reg;if(!r)return;const dx=r.x+ax*r.w,dy=r.y+ay*r.h;if(dx>=this.map.w||dy>=this.map.h||dx+r.w<=0||dy+r.h<=0){this.say('That is outside the map.','#ffb040');sfx('nope');return;}this.copyOp(r.x,r.y,r.w,r.h,dx,dy);this.reg={x:dx,y:dy,w:r.w,h:r.h};},
 clearReg(){const r=this.reg;if(!r)return;this.snap();const op=['B',0,r.x,r.y,r.w,r.h],m=this.map;m.ops.push(op);this.S.op(op);this.afterOp(r.x-2,r.x+r.w+2);sfx('deny');},
 dupObj(ax,ay,o=this.sel){const m=this.map;if(!o)return;if(o.k==='warp'){this.say('Warp stones come in pairs. Place a new one.','#ffb040');sfx('nope');return;}const c=JSON.parse(JSON.stringify(o));delete c.uid;c.x=clamp(o.x+ax*Math.max(24,o.w||0),4,m.w-(o.w||0)-5);c.y=clamp(o.y+ay*Math.max(24,o.h||0),4,m.h-1);this.snap();m.objs.push(c);this.sel=c;this.touch();sfx('assign');},
 copy(){if(this.sel){this.clip={t:'obj',o:JSON.parse(JSON.stringify(this.sel)),n:0};this.say('Copied. Press Ctrl+V to paste.');}else if(this.reg){this.clip={t:'reg',...this.reg};this.say('Land copied. Press Ctrl+V to paste.');}else this.say('Select an object or a region first.','#ffb040');},
 paste(){const c=this.clip;if(!c){this.say('Nothing copied yet.','#ffb040');return;}if(c.t==='reg'){this.tool='paste';this.sel=null;sfx('move');return;}c.n++;const o=JSON.parse(JSON.stringify(c.o));delete o.uid;if(o.k==='warp'){this.say('Warp stones come in pairs. Place a new one.','#ffb040');return;}o.x=clamp(o.x+24*c.n,4,this.map.w-(o.w||0)-5);this.snap();this.map.objs.push(o);this.sel=o;if(this.tool==='region'||this.tool==='paste')this.tool='move';this.touch();sfx('assign');},
