 numEntry(k){const o=this.sel,m=this.map;if(!o)return;dlg.open({title:'Move to '+k.toUpperCase(),la:k.toUpperCase()+' position (pixels from the '+(k==='x'?'left':'top')+')',a:String(Math.round(o[k])),ok:'Move',fn:v=>{const n=parseInt(v,10);if(!Number.isFinite(n))return;this.snap();o[k]=k==='x'?clamp(n,4,m.w-(o.w||0)-5):clamp(n,4,m.h-1);this.touch();}});},
 saveImage(){const m=this.map,[c,x]=mk(m.w,m.h);x.fillStyle='#1c1428';x.fillRect(0,0,m.w,m.h);this.drawMapLayer(x,true);const name=('rabblings-'+(m.name||'map').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')+'.png');c.toBlob(async b=>{if(!b){this.say('Could not make the picture.','#ff6a4e');return;}let ok=false;try{if(!window.claude){const a=document.createElement('a'),u=URL.createObjectURL(b);a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);ok=true;}else{const dl=window.claude.use?await window.claude.use('downloads'):null;if(dl){await dl.save({filename:name,data:b});ok=true;}}}catch(e){}this.say(ok?'Picture saved.':'The picture could not be saved here.',ok?'#9fdc40':'#ffb040');},'image/png');},
 randSkills(set){SK.forEach(k=>set[k]=0);const L=SK.slice().sort(()=>Math.random()-.5).slice(0,4+(Math.random()*3|0));for(const k of L)set[k]=1+(Math.random()*8|0);this.touch();sfx('select');},
 w(sx,sy){return[Math.round((sx-EDX)/this.z+this.cx),Math.round((sy-EDY)/this.z+this.cy)];},
