 clampCam(){const m=this.map,vw=EDW/this.z,vh=EDH/this.z;this.cx=clamp(this.cx,Math.min(0,(m.w-vw)/2),Math.max(0,m.w-vw));this.cy=clamp(this.cy,Math.min(0,m.h-vh),Math.max(0,m.h-vh));},
 mini(){const m=this.map,T=this.T;if(!this.mc)[this.mc,this.mx2]=mk(120,26);const im=this.mx2.createImageData(120,26),c=hex2(THEME[m.theme].ramp[5]);for(let j=0;j<26;j++)for(let i=0;i<120;i++){const k=T.m[((j+.5)/26*T.h|0)*T.w+((i+.5)/120*T.w|0)],o=(j*120+i)*4,col=k===2?[150,160,180]:k===3?[200,150,90]:k?c:[14,10,22];im.data[o]=col[0];im.data[o+1]=col[1];im.data[o+2]=col[2];im.data[o+3]=255;}this.mx2.putImageData(im,0,0);this.miniDirty=0;},
 pick(wx,wy){const O=this.map.objs;for(let i=O.length-1;i>=0;i--){const o=O[i];if(o.lock||o.hide)continue;if(o.w!==undefined&&o.k!=='pool'?wx>=o.x&&wx<o.x+o.w&&(o.h!==undefined?wy>=o.y&&wy<o.y+o.h:wy>=o.y-10&&wy<=o.y+8):o.k==='pool'?wx>=o.x&&wx<=o.x+o.w&&wy>=o.y-6&&wy<=o.y+24:o.k==='door'?Math.abs(wx-o.x)<=20&&wy<=o.y&&wy>=o.y-40:o.k==='hatch'?Math.abs(wx-o.x)<=20&&wy>=o.y-26&&wy<=o.y:Math.abs(wx-o.x)<=12&&Math.abs(wy-o.y+6)<=16)return o;}return null;},
